package com.crm.fees;
import com.crm.fees.repository.FeeReportRepository;import com.crm.fees.service.FeeReportService;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class FeeReportPolicyTest {
 FeeReportRepository repository=mock(FeeReportRepository.class);FeeReportService reports=new FeeReportService(repository);LocalDate from=LocalDate.of(2026,1,1),to=LocalDate.of(2026,1,31);
 @BeforeEach void role(){FeeCyclePolicyTest.role("ADMIN");when(repository.recorded(any(),any(),any(),any(),any())).thenReturn(List.of());when(repository.unrecorded(any(),any(),any(),any(),any())).thenReturn(List.of());}@AfterEach void clear(){SecurityContextHolder.clearContext();}
 FeeReportRepository.Row row(String title,String currency,String amount,String hours){var r=mock(FeeReportRepository.Row.class);when(r.getTitle()).thenReturn(title);when(r.getCurrency()).thenReturn(currency);when(r.getAmount()).thenReturn(amount==null?null:new BigDecimal(amount));when(r.getHours()).thenReturn(hours==null?null:new BigDecimal(hours));when(r.getCount()).thenReturn(1L);return r;}
 @Test void totalsStaySeparateByCurrencyAndOrigin(){doReturn(List.of(row("A","TND","30.85","2.50"),row("B","TND","1.15","0.50"),row("C","EUR","20.00","2"))).when(repository).recorded(any(),any(),any(),any(),any());doReturn(List.of(row("A","TND","30.85","2.50"))).when(repository).unrecorded(any(),any(),any(),any(),any());var r=reports.read(from,to);assertEquals(4,r.lines().size());assertEquals(3,r.totals().size());assertEquals(3,r.customerTotals().size());var t=r.totals().stream().filter(x->x.kind().equals("RECORDED_FEE")&&x.currency().equals("TND")).findFirst().orElseThrow();assertEquals("32.00",t.amount());assertEquals("3.00",t.hours());assertEquals(2,t.count());assertTrue(r.policy().contains("RECORDED_IS_NOT_INVOICED"));}
 @Test void historicalUnknownCurrencyAndExactDurationStayUnknown(){doReturn(List.of(row("Legacy",null,"999","2"),row("Legacy2","TND","3.00",null))).when(repository).recorded(any(),any(),any(),any(),any());var r=reports.read(from,to);assertNull(r.lines().getFirst().amount());assertNull(r.totals().stream().filter(t->t.currency()==null).findFirst().orElseThrow().amount());assertNull(r.totals().stream().filter(t->t.currency()!=null).findFirst().orElseThrow().hours());}
 @Test void emptyPeriodHasNoFabricatedTotals(){var r=reports.read(from,to);assertTrue(r.lines().isEmpty());assertTrue(r.totals().isEmpty());}
 @Test void queryBoundsAndOversizedReportsAreExplicit(){var many=Collections.nCopies(1001,row("A","TND","1","1"));when(repository.recorded(any(),any(),any(),any(),any())).thenReturn(many);assertThrows(IllegalArgumentException.class,()->reports.read(from,to));verify(repository).recorded(eq(from),eq(to),isNull(),isNull(),argThat(p->p.getPageSize()==1001));assertThrows(IllegalArgumentException.class,()->reports.read(from,from.plusDays(366)));}
 @Test void aggregateFailuresDoNotBecomeZero(){when(repository.recorded(any(),any(),any(),any(),any())).thenThrow(new IllegalStateException("synthetic"));assertThrows(IllegalStateException.class,()->reports.read(from,to));}
 @Test void csvIsUtf8BomEscapedAndFormulaSafeWithoutRepeatingTotals(){doReturn(List.of(row("=SUM(1,2) \"test\"","TND","30.85","2.50"))).when(repository).recorded(any(),any(),any(),any(),any());String csv=new String(reports.csv(from,to),java.nio.charset.StandardCharsets.UTF_8);assertTrue(csv.startsWith("\uFEFFclassification,"));assertTrue(csv.contains("\"'=SUM(1,2) \"\"test\"\"\""));assertEquals(2,csv.lines().count());for(String s:List.of("=1","+1","-1","@x"," x","\tx"))assertTrue(FeeReportService.cell(s).startsWith("\"'"));}
 @Test void personalRolesCannotReadOrExport(){for(String role:List.of("EMPLOYEE","CLIENT")){FeeCyclePolicyTest.role(role);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->reports.read(from,to));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->reports.csv(from,to));}verifyNoInteractions(repository);}
}
